const jsonLd = "{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":\"MedicalWebPage\",\"name\":\"Infiltrations du genou : « régénératives » vs non régénératives | Dr. Nuno Camelo Porto\",\"url\":\"https://www.consultajoelho.pt/fr/infiltracoes\",\"dateModified\":\"2026-07-24\",\"lastReviewed\":\"2026-07-24\",\"reviewedBy\":{\"@type\":\"Physician\",\"name\":\"Dr. Nuno Camelo Barbosa\",\"url\":\"https://www.consultajoelho.pt/nuno-camelo-especialista-cirurgia-joelho\",\"medicalSpecialty\":\"Orthopedic\",\"sameAs\":[\"https://orcid.org/0000-0002-7443-4085\",\"https://www.researchgate.net/profile/Nuno-Camelo-Barbosa\",\"https://scholar.google.com/citations?user=iTCpAfYAAAAJ\",\"https://linkedin.com/in/nuno-camelo-barbosa-07b37277\"]},\"citation\":[\"https://doi.org/10.1001/jama.2017.5283\",\"https://doi.org/10.1177/03635465241246524\",\"https://doi.org/10.1177/0363546520909397\",\"https://oarsi.org/research-oarsi-success/oarsi-guidelines-non-surgical-management-knee-hip-and-polyarticular\",\"https://www.aaos.org/globalassets/quality-and-practice-resources/osteoarthritis-of-the-knee/oak3cpg.pdf\"]},{\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Combien coûtent les infiltrations du genou ?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Le prix dépend du type d'infiltration et de la voie d'accès (SNS, assurance ou privé). En privé et à titre indicatif :• Corticoïde — à partir d'environ 100 €.• Acide hyaluronique (viscosupplémentation) — à partir d'environ 200 € (selon la marque et le protocole : dose unique à haut poids moléculaire ou 3–5 infiltrations).• PRP (plasma riche en plaquettes) — à partir d'environ 350 €.• Cellules souches et Artrosamid® (options plus récentes) — à partir d'environ 2 500 €, mais encore sans preuves scientifiques robustes justifiant le coût.Le prix final dépend du produit, du nombre de séances et de l'établissement.\"}},{\"@type\":\"Question\",\"name\":\"L'infiltration va-t-elle guérir mon arthrose ?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Aucune infiltration ne guérit l'arthrose — il s'agit d'une maladie chronique dégénérative sans traitement curatif définitif connu (hormis la prothèse du genou). Ce que les infiltrations peuvent faire, c'est contrôler les symptômes, ralentir la progression (surtout le PRP et l'AH) et améliorer la qualité de vie. L'objectif est de gérer l'arthrose sur le long terme, non d'éliminer la maladie.\"}},{\"@type\":\"Question\",\"name\":\"Puis-je recevoir des corticoïdes de façon répétée s'ils me soulagent ?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"C'est l'une des questions les plus importantes en pratique clinique. Les corticoïdes sont efficaces à court terme, mais les études IRM à long terme montrent une perte du volume de cartilage en cas d'usage répété. La recommandation actuelle est de ne pas dépasser 3 à 4 infiltrations par articulation et par an, et d'explorer les alternatives dites « régénératives » — PRP ou acide hyaluronique — pour le contrôle de la douleur chronique.\"}},{\"@type\":\"Question\",\"name\":\"Le PRP est-il remboursé par le SNS ou par l'assurance maladie ?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Au Portugal, le PRP n'est actuellement pas remboursé par le service public de santé (SNS) pour l'arthrose du genou. Certaines assurances maladie privées le couvrent partiellement, mais cela varie selon le contrat. L'acide hyaluronique est remboursé par le SNS sous certaines conditions. Le corticoïde intra-articulaire est largement remboursé. Je recommande de confirmer la couverture auprès de votre assureur avant la consultation.\"}},{\"@type\":\"Question\",\"name\":\"Puis-je recevoir une infiltration puis être opéré du genou ?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Cela dépend du type. Les corticoïdes intra-articulaires augmentent le risque d'infection périchirurgicale — la recommandation est un intervalle minimum de 3 mois avant toute chirurgie articulaire. L'acide hyaluronique et le PRP n'ont pas cette contre-indication. Il est essentiel d'informer le chirurgien de toute infiltration récente avant une intervention.\"}},{\"@type\":\"Question\",\"name\":\"Je suis diabétique. Puis-je recevoir une infiltration de corticoïde ?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Oui, mais avec prudence. Les corticoïdes intra-articulaires peuvent provoquer une hausse transitoire de la glycémie dans les 24 à 72 heures après l'infiltration — surtout chez les diabétiques dont le contrôle est moins rigoureux. Le risque est réel mais généralement gérable. Informez toujours votre médecin de l'état de votre diabète. Chez les patients diabétiques atteints d'arthrose du genou chronique, les options dites « régénératives » — PRP ou acide hyaluronique — sont souvent préférables pour un usage répété.\"}},{\"@type\":\"Question\",\"name\":\"Quelle est la différence entre les marques d'acide hyaluronique (Ostenil, Durolane, Monovisc) ?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"La principale différence réside dans le poids moléculaire et la présence ou l'absence de réticulation (liaisons croisées entre les chaînes d'AH). Les produits réticulés à haut poids moléculaire (Durolane, Monovisc) sont administrés en une seule infiltration et ont une durée théorique plus longue. Les produits à bas poids moléculaire (Ostenil) nécessitent 3 à 5 infiltrations hebdomadaires mais ont un coût unitaire plus faible. Le choix dépend du degré d'arthrose, de la préférence du patient et du contexte clinique.\"}}]},{\"@type\":\"BreadcrumbList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"name\":\"Accueil\",\"item\":\"https://www.consultajoelho.pt/fr\"},{\"@type\":\"ListItem\",\"position\":2,\"name\":\"Infiltrations du genou : « régénératives » vs non régénératives\",\"item\":\"https://www.consultajoelho.pt/fr/infiltracoes\"}]}]}";
const pageScript = "\nfunction toggleCard(header) {\n  const body = header.nextElementSibling;\n  const toggle = header.querySelector('.treatment-toggle');\n  const isOpen = body.classList.contains('open');\n  body.classList.toggle('open', !isOpen);\n  toggle.classList.toggle('open', !isOpen);\n}\n\nfunction toggleFAQ(item) {\n  item.classList.toggle('open');\n}\n\n// Open first card by default\ndocument.addEventListener('DOMContentLoaded', () => {\n  const firstHeader = document.querySelector('.treatment-header');\n  if (firstHeader) toggleCard(firstHeader);\n  document.querySelectorAll('.faq-item')[0]?.classList.add('open');\n});\n";

